import{_ as r,B as t,o as l,c as d,a8 as c,a as e,E as s,f as i}from"./chunks/framework.CNIpabDg.js";const b=JSON.parse('{"title":"Application metadata","description":"Shared launch and shortcut metadata for Xila applications.","frontmatter":{"layout":"doc","docType":"explanation","description":"Shared launch and shortcut metadata for Xila applications."},"headers":[],"relativePath":"explanation/architecture/libraries/application_metadata.md","filePath":"explanation/architecture/libraries/application_metadata.md","lastUpdated":1792488559000}'),h={name:"explanation/architecture/libraries/application_metadata.md"};function p(k,a,u,m,g,y){const n=t("HostReference"),o=t("CodeReference");return l(),d("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1792488559000"},[a[4]||(a[4]=c(`<h1 id="application-metadata" tabindex="-1">Application metadata <a class="header-anchor" href="#application-metadata" aria-label="Permalink to &quot;Application metadata&quot;">​</a></h1><p>The <code>application_metadata</code> library centralizes native and guest application names, seed-install markers and shortcut JSON construction. Host examples, installers and filesystem image generation can share these definitions without duplicating their application inventory.</p><p>It is a reusable data/formatting library with no independent runtime manager.</p><h2 id="public-contract" tabindex="-1">Public contract <a class="header-anchor" href="#public-contract" aria-label="Permalink to &quot;Public contract&quot;">​</a></h2><p>The library is <code>no_std</code> with <code>alloc</code>, and exposes two compile-time application inventories:</p><ul><li><code>GUESTS</code>: <code>calculator</code>, <code>clock</code>, <code>pixel_painter</code>, <code>synth</code>, <code>text_editor</code> and <code>weather</code>.</li><li><code>NATIVE</code>: <code>file_manager</code>, <code>terminal</code> and <code>settings</code>, plus <code>debug</code> on Unix builds.</li></ul><p>These arrays drive shared knowledge about installation and launch; they do <strong>not</strong> discover installed binaries dynamically. A runtime may have fewer or different executables than the inventory, so consumers should still check the VFS.</p><p><code>shortcut(name: &amp;str) -&gt; Option&lt;String&gt;</code> emits a JSON string containing a display name, executable command, arguments, terminal flag, short icon text and RGB icon color. Guest shortcuts invoke <code>/binaries/wasm</code> with <code>&quot;/binaries/&lt;guest&gt;&quot;</code> as an argument; native shortcuts invoke their own <code>/binaries/&lt;name&gt;</code> path directly. Unknown names return <code>None</code>.</p><div class="language-rust vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> guest </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> application_metadata</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shortcut</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;clock&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">expect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;known app&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">assert!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(guest</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">contains</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/binaries/wasm&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">));</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">assert!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">application_metadata</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shortcut</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;unknown&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">is_none</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">());</span></span></code></pre></div><h2 id="seed-image-handshake" tabindex="-1">Seed image handshake <a class="header-anchor" href="#seed-image-handshake" aria-label="Permalink to &quot;Seed image handshake&quot;">​</a></h2><p><code>PENDING_PATH</code> is <code>/system/.seed-pending</code>, with exact marker bytes <code>PENDING_CONTENT = b&quot;xila-seed-v1\\n&quot;</code>. The authentication library uses these to <strong>authorize initial account provisioning</strong> only for an explicitly marked reference image. Unmarked existing disks should not automatically reset administrator credentials or recreate accounts.</p><p>The shortcut JSON is assembled manually, not via a general JSON serializer; names and icon values are drawn from a fixed internal match table. Adding a new application requires updating both the appropriate inventory and <code>shortcut</code>, including its launch mode, label, icon and color. Selected labels are resolved at build time through <code>embedded-i18n</code>.</p><h2 id="ownership-limitations-and-references" tabindex="-1">Ownership, limitations and references <a class="header-anchor" href="#ownership-limitations-and-references" aria-label="Permalink to &quot;Ownership, limitations and references&quot;">​</a></h2><p>There is no singleton or mutable registry; all returned shortcut strings are owned by the caller. The <code>#[cfg(unix)]</code> inventory condition is a <strong>compile-target decision</strong>, not a runtime OS probe.</p>`,14)),e("ul",null,[e("li",null,[s(n,{crate:"application_metadata"}),a[0]||(a[0]=i(" — Rustdoc.",-1))]),e("li",null,[s(o,{path:"libraries/application_metadata/src/lib.rs"}),a[1]||(a[1]=i(" — inventories, seed constants and JSON format.",-1))]),a[2]||(a[2]=e("li",null,[e("a",{href:"/explanation/architecture/libraries/authentication.html"},"Authentication"),i(" — reads the seed marker.")],-1)),a[3]||(a[3]=e("li",null,[e("a",{href:"/explanation/architecture/libraries/executable.html"},"Executable"),i(" — consumes launch paths.")],-1))])])}const f=r(h,[["render",p]]);export{b as __pageData,f as default};
